export function childTestGallery(filters,parent,search){
 if(filters.audience&&filters.audience!=='kids'||parent&&!['Одежда','Верхняя одежда'].includes(parent)||search||filters.categories?.length&&!filters.categories.includes('Пальто'))return '';
 return `<section class="child-test-gallery" aria-label="Тесты детских моделей"><h2>Тесты детских моделей</h2><p class="small muted">Результаты генерации FASHN на тестовом пальто. Не продаются и не входят в количество найденных товаров. Нажмите фото для просмотра в полном размере.</p><div class="child-test-grid">${['girl','boy'].flatMap(gender=>['7-9','12-14'].map(age=>{const label=`${gender==='girl'?'Девочка':'Мальчик'} · ${age} лет`,image=side=>`<a href="/assets/child-tests/${gender}-${age}-${side}.jpg" target="_blank" rel="noopener"><img src="/assets/child-tests/${gender}-${age}-${side}.jpg" alt="${label}, ${side==='front'?'спереди':'сзади'}" loading="lazy"></a>`;return `<article class="child-test-card"><h3>${label}</h3>${image('front')}<details><summary>Посмотреть сзади</summary>${image('back')}</details><span class="small muted">Тест · не продаётся</span></article>`;})).join('')}</div></section>`;
}
